// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, address _target) public {
        Reverter reverter = new Reverter();
        address target = address(reverter);

        vm.assume(_value > 0);
        vm.deal(address(c), _value);

        bool reverted;
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, _value));
        if (!success) {
            reverted = true;
        } else {
            reverted = false;
        }

        assertTrue(reverted);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
